using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Playables;using UnityEngine.Animations;using Unity.DemoTeam.Hair;using Sandbox.CharacterSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VerifyLioraMergedHierarchy {
 const string Folder="Assets/_Sandbox/Characters/Liora/Candidate/";const string Data="Data/Liora/HierarchyRepair/";
 static Vector3 Read(BinaryReader r)=>new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());
 static Vector3[] Skin(SkinnedMeshRenderer r,Transform root){var m=r.sharedMesh;var p=m.vertices;var delta=new Vector3[p.Length];for(int s=0;s<m.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;m.GetBlendShapeFrameVertices(s,0,delta,null,null);for(int j=0;j<p.Length;j++)p[j]+=delta[j]*w;}var mat=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*m.bindposes[j]).ToArray();var result=new Vector3[p.Length];using(var counts=m.GetBonesPerVertex())using(var weights=m.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++)for(int k=0;k<counts[j];k++){var w=weights[at++];result[j]+=mat[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;}}return result;}
 static void Set(SkinnedMeshRenderer face,string name,float weight){int i=face.sharedMesh.GetBlendShapeIndex(name);if(i<0)throw new Exception("Missing shape "+name);face.SetBlendShapeWeight(i,weight);}
 public static object Static(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string temporary="Assets/__LioraHierarchyBefore.prefab";if(File.Exists(temporary))throw new Exception("Temporary asset exists");File.Copy(Data+"Before/Liora_Candidate.prefab",temporary);AssetDatabase.ImportAsset(temporary);
 GameObject root=null,before=null;
 try{root=PrefabUtility.LoadPrefabContents(Folder+"Liora_Candidate.prefab");before=PrefabUtility.LoadPrefabContents(temporary);
 var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);if(skins.Length!=2||!skins.Select(r=>r.name).OrderBy(s=>s).SequenceEqual(new[]{"Face","Outfit"}))throw new Exception("Expected only Face and Outfit");
 if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name.StartsWith("BAKED_")))throw new Exception("BAKED objects remain in candidate");
 var face=skins.Single(r=>r.name=="Face");var outfit=skins.Single(r=>r.name=="Outfit");var oldFace=before.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_head_lod0_mesh");var oldOutfit=before.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_Outfits");var sections=JObject.Parse(File.ReadAllText(Data+"sections.json"))["sections"];
 if(outfit.sharedMesh!=oldOutfit.sharedMesh)throw new Exception("Outfit mesh changed");var errors=root.GetComponent<Character>().ValidateConfiguration();errors.AddRange(root.GetComponent<CharacterFlowController>().ValidateConfiguration());if(errors.Count>0)throw new Exception(string.Join(";",errors));
 int arrays=0;using(var r=new BinaryReader(File.OpenRead(Data+"desired_shapes.bin"))){int n=r.ReadInt32(),shapes=r.ReadInt32();var p=new Vector3[n];var normal=new Vector3[n];var t=new Vector3[n];var ap=new Vector3[n];var an=new Vector3[n];var at=new Vector3[n];if(n!=face.sharedMesh.vertexCount||shapes!=face.sharedMesh.blendShapeCount)throw new Exception("Merged shape dimensions changed");for(int s=0;s<shapes;s++){for(int j=0;j<n;j++){p[j]=Read(r);normal[j]=Read(r);t[j]=Read(r);}face.sharedMesh.GetBlendShapeFrameVertices(s,0,ap,an,at);if(!p.SequenceEqual(ap)||!normal.SequenceEqual(an)||!t.SequenceEqual(at))throw new Exception("Sparse array changed "+s);arrays+=3;}}
 var head=oldFace.sharedMesh;var merged=face.sharedMesh;if(!head.vertices.SequenceEqual(merged.vertices.Take(head.vertexCount))||!head.normals.SequenceEqual(merged.normals.Take(head.vertexCount))||!head.tangents.SequenceEqual(merged.tangents.Take(head.vertexCount)))throw new Exception("Primary head base records changed");for(int sub=0;sub<head.subMeshCount;sub++)if(!head.GetTriangles(sub).SequenceEqual(merged.GetTriangles(sub)))throw new Exception("Head triangle ordering changed");
 var oldSkins=before.GetComponentsInChildren<SkinnedMeshRenderer>(true).ToDictionary(r=>r.name);float maxWorld=0;int comparisons=0;
 foreach(string name in new[]{"Basis"}.Concat(Enumerable.Range(0,merged.blendShapeCount).Select(merged.GetBlendShapeName))){if(name!="Basis"){Set(oldFace,name,100);Set(face,name,100);}before.GetComponent<CharacterFacialMeshSync>().Apply();root.GetComponent<CharacterFacialMeshSync>()?.Apply();var actual=Skin(face,root.transform);
 foreach(var section in sections){var expected=Skin(oldSkins[(string)section["name"]],before.transform);int offset=(int)section["offset"];for(int j=0;j<expected.Length;j++)maxWorld=Mathf.Max(maxWorld,Vector3.Distance(expected[j],actual[offset+j]));comparisons++;}
 if(name!="Basis"){Set(oldFace,name,0);Set(face,name,0);}}
 if(maxWorld>2e-6f)throw new Exception("World shape mismatch "+maxWorld);
 var driver=root.GetComponentInChildren<uLipSync.uLipSyncBlendShape>(true);var lip=root.GetComponentInChildren<uLipSync.uLipSync>(true);var expression=root.GetComponentInChildren<ExpressionModule>(true);if(driver.gameObject!=face.gameObject||driver.skinnedMeshRenderer!=face||expression.Face!=face||lip.onLipSyncUpdate.GetPersistentTarget(0)!=driver)throw new Exception("Facial reference remapping failed");
 var a=root.GetComponentInChildren<Animator>(true);if(root.GetComponentsInChildren<Animator>(true).Length!=1||!a.avatar.isValid||!a.avatar.isHuman)throw new Exception("Avatar invalid");
 var hair=root.GetComponentInChildren<HairInstance>(true);var oldHair=before.GetComponentInChildren<HairInstance>(true);if(hair.strandGroupProviders[0].hairAsset!=oldHair.strandGroupProviders[0].hairAsset||hair.settingsExecutive.updateSimulationInEditor||hair.settingsExecutive.updateSimulationRate!=HairInstance.SettingsExecutive.UpdateRate.Fixed30Hz||hair.strandGroupDefaults.settingsGeometry.strandScale!=HairSim.SettingsGeometry.StrandScale.Fixed)throw new Exception("Groom changed");
 var boundary=hair.settingsEnvironment.boundaryResident.Single();var oldBoundary=oldHair.settingsEnvironment.boundaryResident.Single();if(boundary.settingsSDF.kSDFTexture!=oldBoundary.settingsSDF.kSDFTexture)throw new Exception("Collision changed");
 float matrixError=0;var hm=root.transform.worldToLocalMatrix*hair.transform.localToWorldMatrix;var om=before.transform.worldToLocalMatrix*oldHair.transform.localToWorldMatrix;for(int j=0;j<16;j++)matrixError=Mathf.Max(matrixError,Mathf.Abs(hm[j]-om[j]));if(matrixError>1e-6f)throw new Exception("Hair attachment moved");
 var refs=new List<string>();foreach(var c in root.GetComponentsInChildren<Component>(true).Where(c=>c&&!(c is Transform))){var so=new SerializedObject(c);var p=so.GetIterator();while(p.Next(true))if(!p.propertyPath.StartsWith("m_")&&p.propertyType==SerializedPropertyType.ObjectReference&&p.objectReferenceValue){var value=p.objectReferenceValue;var owner=(value as Component)?.transform??(value as GameObject)?.transform;if(owner&&owner!=root.transform&&!owner.IsChildOf(root.transform))refs.Add(c.GetType().Name+"."+p.propertyPath);}}if(refs.Count>0)throw new Exception("Stale references "+string.Join(";",refs));
 int missing=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));if(missing>0)throw new Exception("Missing scripts");
 var referenceLayouts=new[]{"Assets/_Sandbox/Characters/Ethan/Ethan.prefab","Assets/_Sandbox/Characters/Ethan_V2/Candidate/EthanV2_Candidate.prefab","Assets/_Sandbox/Characters/Jiwoo/Jiwoo_Normalized.prefab"}.Select(path=>{var g=AssetDatabase.LoadAssetAtPath<GameObject>(path);return new{path,topLevel=Enumerable.Range(0,g.transform.childCount).Select(j=>g.transform.GetChild(j).name),renderers=g.GetComponentsInChildren<SkinnedMeshRenderer>(true).Select(r=>r.name)};});
 var report=new{passed=true,renderers=skins.Select(r=>r.name),topLevel=Enumerable.Range(0,root.transform.childCount).Select(j=>root.transform.GetChild(j).name),faceVertices=merged.vertexCount,faceTriangles=merged.triangles.Length/3,faceShapes=merged.blendShapeCount,exactDenseArrayComparisons=arrays,worldMeshShapeComparisons=comparisons,maxWorldShapeErrorM=maxWorld,headFirstAndUnchanged=true,outfitMeshUnchanged=true,avatarUnchanged=a.avatar==before.GetComponentInChildren<Animator>(true).avatar,scalpAssetAndCollisionPreserved=true,hairAttachmentMatrixError=matrixError,facialReferencesRemapped=true,noStaleReferences=true,configurationErrors=errors,missingScripts=missing,referenceLayouts,sceneSaved=false,playModeTested=false};File.WriteAllText(Data+"static_verification.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{passed=true,comparisons,maxWorldShapeErrorM=maxWorld,renderers=2};
 }finally{if(before)PrefabUtility.UnloadPrefabContents(before);if(root)PrefabUtility.UnloadPrefabContents(root);AssetDatabase.DeleteAsset(temporary);}
 }
 public static object Motion(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents(Folder+"Liora_Candidate.prefab");
 try{var animator=root.GetComponentInChildren<Animator>(true);var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));var baseline=skins.ToDictionary(r=>r,r=>Skin(r,root.transform));Action reset=()=>{foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}};
 var definitions=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox/Data"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion).GroupBy(d=>d.Clip).Select(g=>g.First());var samples=new List<object>();
 foreach(var definition in definitions){reset();var graph=PlayableGraph.Create("Merged Liora disposable motion check");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,definition.Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();float maxRadius=0,maxMove=0;foreach(float phase in new[]{0f,.25f,.5f,.75f,1f}){p.SetTime(definition.Clip.length*phase);graph.Evaluate(0);foreach(var r in skins){var values=Skin(r,root.transform);float bound=values.Max(v=>v.magnitude);if(!float.IsFinite(bound)||bound>3f)throw new Exception("Invalid pose "+definition.name);maxRadius=Mathf.Max(maxRadius,bound);for(int j=0;j<values.Length;j++)maxMove=Mathf.Max(maxMove,Vector3.Distance(values[j],baseline[r][j]));}}if(maxMove<.001f)throw new Exception("No animation motion");samples.Add(new{name=definition.name,maxRadiusM=maxRadius,maxMovementM=maxMove});}finally{graph.Destroy();}}
 reset();int fingers=0;foreach(var side in new[]{"Left","Right"})foreach(var finger in new[]{"Thumb","Index","Middle","Ring","Little"})foreach(var joint in new[]{"Proximal","Intermediate","Distal"}){var bone=animator.GetBoneTransform((HumanBodyBones)Enum.Parse(typeof(HumanBodyBones),side+finger+joint));if(!bone)throw new Exception("Missing finger mapping");fingers++;}
 var report=new{passed=true,poseSamples=samples.Count*5,clips=samples,fingerMappings=fingers,sceneSaved=false,playModeTested=false};File.WriteAllText(Data+"motion_verification.json",JsonConvert.SerializeObject(report,Formatting.Indented));return report;
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
}
